100	// Adjust a block that was allocated aligned, to the actual start of the block in the page.
101	// note: this can be called from `mi_free_generic_mt` where a non-owning thread accesses the
102	// `page_woffset` and `block_size` fields; however these are constant and the page won't be
103	// deallocated (as the block we are freeing keeps it alive) and thus safe to read concurrently.
104	mi_block_t* _mi_page_ptr_unalign(const mi_page_t* page, const void* p) {
105	  mi_assert_internal(page!=NULL && p!=NULL);
106	
107	  const size_t diff = (uint8_t*)p - mi_page_start(page);
108	  const size_t block_size = mi_page_block_size(page);
109	  size_t adjust = diff & (block_size - 1); 
110	  if mi_unlikely(!_mi_is_power_of_two(block_size)) {
111	    adjust = diff % block_size;     
112	  }
113	  return (mi_block_t*)((uintptr_t)p - adjust);
114	}
115	
116	static inline mi_block_t* mi_validate_block_from_ptr( const mi_page_t* page, const void* p ) {
117	  mi_assert(_mi_page_ptr_unalign(page,p) == (mi_block_t*)p); // should never be an interior pointer
118	  #if MI_SECURE > 0
119	  // in secure mode we always unalign to guard against free-ing interior pointers
120	  return _mi_page_ptr_unalign(page,p);
121	  #else
122	  MI_UNUSED(page);
123	  return (mi_block_t*)p;
124	  #endif
125	}
