170	// Get the page belonging to a pointer
171	// Does further checks in debug mode to see if this was a valid pointer.
172	static inline bool mi_validate_ptr_page_nonnull(const void* p, const char* msg, bool free_small, mi_page_t** ppage)
173	{
174	  MI_UNUSED_RELEASE(msg);
175	  #if MI_DEBUG
176	  if mi_unlikely(((uintptr_t)p & (MI_INTPTR_SIZE - 1)) != 0 && !mi_option_is_enabled(mi_option_guarded_precise)) {
177	    _mi_error_message(EINVAL, "%s: invalid (unaligned) pointer: %p\n", msg, p);
178	    return false;
179	  }
180	  #endif
181	  
182	  mi_page_t* page;
183	  #if MI_PAGE_META_IS_ALIGNED
184	    page = _mi_aligned_ptr_page0(p);
185	    if mi_unlikely(page==NULL) return false; // p==NULL => page==NULL    
186	    #if MI_DEBUG 
187	    mi_page_t* const cpage = _mi_checked_ptr_page(p);
188	    if mi_unlikely(cpage==NULL) { _mi_error_message(EINVAL, "%s: invalid pointer: %p\n", msg, p); }
189	    #endif
190	    
191	    #if MI_SMALL_PAGE_SIZE == MI_ARENA_SLICE_SIZE
192	    // for mi_free_small we can avoid a load-acquire
193	    if (free_small) { mi_assert_internal(page == mi_atomic_load_ptr_acquire(mi_page_t,&page->self)); } 
194	               else { page = mi_atomic_load_ptr_acquire(mi_page_t,&page->self); }
195	    #else
196	    MI_UNUSED(free_small);
197	    page = mi_atomic_load_ptr_acquire(mi_page_t,&page->self);
198	    #endif
199	
200	    mi_assert_internal(page!=NULL);
201	    mi_assert(cpage==page /* page_map lookup should be the same as aligned lookup */ );  
202	  #else
203	    MI_UNUSED(free_small);
204	    page = _mi_ptr_page(p);
205	    if mi_unlikely(page==NULL) {
206	      #if MI_DEBUG
207	      if (p!=NULL) { _mi_error_message(EINVAL, "%s: invalid pointer: %p\n", msg, p); }
208	      #endif
209	      return false;
210	    }
211	  #endif
212	  *ppage = page;
213	  return true;
214	}
