251	void mi_free(void* p) mi_attr_noexcept {  
252	  mi_page_t* page; 
253	  if mi_likely(mi_validate_ptr_page_nonnull(p,"mi_free",false,&page)) {    
254	    mi_free_nonnull(p, page, NULL, true /* allow collect? */);
255	  }
256	}
