268	void mi_free_small(void* p) mi_attr_noexcept {
269	  #if MI_PAGE_META_SMALL_IS_ALIGNED 
270	    // deprecated: We can only call `mi_free_small` for pointers allocated with `mi_(heap_)malloc_small`.
271	    // If we keep page info in front of the page area for small objects, we can find the info
272	    // just by aligning down the pointer instead of looking it up in the page map.    
273	    #if MI_GUARDED 
274	    #warning "MI_OPT_FREE_SMALL (MI_PAGE_META_SMALL_IS_ALIGNED) ignored as MI_GUARDED is defined"
275	    mi_free(p);
276	    #elif MI_ARENA_SLICE_ALIGN < MI_SMALL_PAGE_SIZE
277	    #warning "MI_OPT_FREE_SMALL (MI_PAGE_META_SMALL_IS_ALIGNED) ignored as the MI_ARENA_SLICE_ALIGN is less than the small page size"
278	    mi_free(p);
279	    #else
280	      mi_page_t* const page = (mi_page_t*)_mi_align_down_ptr(p,MI_SMALL_PAGE_SIZE);
281	      mi_assert(page == mi_validate_ptr_page(p,"mi_free_small"));
282	      mi_assert((void*)page == _mi_align_down_ptr(mi_page_start(page),MI_SMALL_PAGE_SIZE));
283	      mi_assert(page->block_size <= mi_good_size(MI_SMALL_SIZE_MAX));  // note: not `MI_SMALL_MAX_OBJ_SIZE` as we need to match `mi_(heap_)malloc_small`
284	      mi_free_nonnull(p, page, NULL, true);
285	    #endif
286	  #else
287	    mi_page_t* page; 
288	    if mi_likely(mi_validate_ptr_page_nonnull(p,"mi_free_small",true /* is_small? */,&page)) {    
289	      mi_free_nonnull(p, page, NULL, true /* allow collect? */);
290	    }  
291	  #endif  
292	}
