708	// Initialize a fresh page (that is already partially initialized)
709	mi_decl_nodiscard bool _mi_page_init(mi_theap_t* theap, mi_page_t* page) {
710	  mi_assert(page != NULL);
711	  mi_assert(theap!=NULL);
712	  // page->heap = (_mi_is_heap_main(_mi_theap_heap(theap)) ? NULL : _mi_theap_heap(theap)); // faster for `mi_page_associated_theap`
713	  // mi_page_set_theap(page, theap);
714	
715	  size_t page_size;
716	  uint8_t* page_start = mi_page_area(page, &page_size); MI_UNUSED(page_start);
717	  mi_track_mem_noaccess(page_start,page_size);
718	  mi_assert_internal(page_size / mi_page_block_size(page) < (1L<<16));
719	  mi_assert_internal(page->reserved > 0);
720	  #if (MI_PADDING || MI_ENCODE_FREELIST)
721	  page->keys[0] = _mi_theap_random_next(theap);
722	  #if MI_PAGE_KEY_COUNT==2
723	  page->keys[1] = _mi_theap_random_next(theap);
724	  #endif
725	  #endif
726	  #if MI_DEBUG>2
727	  if (page->memid.initially_zero) {
728	    mi_track_mem_defined(mi_page_start(page), mi_page_committed(page));
729	    mi_assert_expensive(mi_mem_is_zero(page_start, mi_page_committed(page)));
730	  }
731	  #endif
732	
733	  mi_assert_internal(page->heap != NULL);
734	  mi_assert_internal(page->heap == _mi_theap_heap(theap));
735	  mi_assert_internal(page->theap!=NULL);
736	  mi_assert_internal(page->theap == mi_page_theap(page));
737	  mi_assert_internal(page->capacity == 0);
738	  mi_assert_internal(page->free == NULL);
739	  mi_assert_internal(page->used == 0);
740	  mi_assert_internal(mi_page_is_owned(page));
741	  mi_assert_internal(page->xthread_free == 1);
742	  mi_assert_internal(page->next == NULL);
743	  mi_assert_internal(page->prev == NULL);
744	  mi_assert_internal(page->retire_expire == 0);
745	  mi_assert_internal(!mi_page_has_interior_pointers(page));
746	  #if (MI_PADDING || MI_ENCODE_FREELIST)
747	  mi_assert_internal(page->keys[0] != 0);
748	  #if MI_PAGE_KEY_COUNT==2
749	  mi_assert_internal(page->keys[1] != 0);
750	  #endif
751	  #endif
752	  mi_assert_expensive(mi_page_is_valid_init(page));
753	
754	  // initialize an initial free list
755	  if (!mi_page_extend_free(theap,page)) return false;
756	  mi_assert(mi_page_immediate_available(page));
757	  return true;
758	}
