37	    mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
38	  }
39	
40	  // check the free list
41	  mi_block_t* const block = page->free;
42	  const mi_used_t used = page->used;
43	  #if defined(__GNUC__) 
44	  __asm("" : : : "memory");  // alway load used before the test
45	  #endif  
46	  if (block == NULL) {
47	    return _mi_malloc_generic(theap, size, (zero ? 1 : 0), ppage);
48	  }
49	  mi_assert_internal(block != NULL && _mi_ptr_page(block) == page);
50	  if (ppage != NULL) { *ppage = page; };
51	
52	  // pop from the free list
53	  mi_block_t* next = mi_block_next(page,block);
54	  mi_track_mem_undefined(block,sizeof(*block));
55	  block->next = 0;  // don't leak internal data
56	  page->free = next;
57	  page->used = used+1;
58	  mi_assert_internal(page->free == NULL || _mi_ptr_page(page->free) == page);
59	  mi_assert_internal(page->block_size < MI_MAX_ALIGN_SIZE || _mi_is_aligned(block, MI_MAX_ALIGN_SIZE));
60	
61	  #if MI_DEBUG>3
62	  if (page->free_is_zero && size > sizeof(*block)) {
63	    mi_assert_expensive(mi_mem_is_zero(block+1,size - sizeof(*block)));
64	  }
65	  #endif
66	
67	  // allow use of the block internally
68	  // note: when tracking we need to avoid ever touching the MI_PADDING since
69	  // that is tracked by valgrind etc. as non-accessible (through the red-zone, see `mimalloc/track.h`)
70	  const size_t bsize = mi_page_usable_block_size(page);
71	  mi_track_mem_undefined(block, bsize);
